1	import { beforeEach, describe, expect, it } from "vitest";
2	import { loadPrefs } from "./settings";
3	
4	// Minimal localStorage for the node test environment.
5	const store = new Map<string, string>();
6	globalThis.localStorage = {
7	  getItem: (k) => store.get(k) ?? null,
8	  setItem: (k, v) => void store.set(k, String(v)),
9	  removeItem: (k) => void store.delete(k),
10	  clear: () => store.clear(),
11	  key: () => null,
12	  get length() {
13	    return store.size;
14	  },
15	} as Storage;
16	
17	describe("loadPrefs", () => {
18	  beforeEach(() => store.clear());
19	
20	  it("migrates v1 prefs, keeping user settings but taking the new always-armed default", () => {
21	    store.set("mise.cook-prefs", JSON.stringify({ showCamera: false, gesture: { delegate: "CPU", alwaysArmed: false } }));
22	    const p = loadPrefs();
23	    expect(p.showCamera).toBe(false);
24	    expect(p.gesture.delegate).toBe("CPU");
25	    expect(p.gesture.alwaysArmed).toBe(true);
26	    expect(store.has("mise.cook-prefs")).toBe(false);
27	    expect(store.has("mise.cook-prefs.v2")).toBe(true);
28	  });
29	
30	  it("v2 prefs win and keep an explicit alwaysArmed=false", () => {
31	    store.set("mise.cook-prefs.v2", JSON.stringify({ gesture: { alwaysArmed: false } }));
32	    expect(loadPrefs().gesture.alwaysArmed).toBe(false);
33	  });
34	
35	  it("defaults when nothing is saved", () => {
36	    expect(loadPrefs().gesture.alwaysArmed).toBe(true);
37	  });
38	});
