1	import type { StepTimer } from "@/contracts";
2	
3	// SPEC F11 recovery: {sessionId, stepIndex, timers, updatedAt} on every change; offer resume if < 12 h old.
4	const MAX_AGE_MS = 12 * 3600_000;
5	const key = (sessionId: string) => `mise.cook.${sessionId}`;
6	
7	export interface SavedCook {
8	  sessionId: string;
9	  stepIndex: number;
10	  timers: StepTimer[];
11	  updatedAt: number;
12	}
13	
14	export function saveCook(s: SavedCook) {
15	  try {
16	    localStorage.setItem(key(s.sessionId), JSON.stringify(s));
17	  } catch {} // private mode / quota: resume is a convenience
18	}
19	
20	export function loadCook(sessionId: string, now = Date.now()): SavedCook | null {
21	  try {
22	    const s = JSON.parse(localStorage.getItem(key(sessionId)) ?? "null") as SavedCook | null;
23	    return s && s.sessionId === sessionId && now - s.updatedAt < MAX_AGE_MS ? s : null;
24	  } catch {
25	    return null;
26	  }
27	}
28	
29	export function clearCook(sessionId: string) {
30	  try {
31	    localStorage.removeItem(key(sessionId));
32	  } catch {}
33	}
