1	import { afterEach, describe, expect, it, vi } from 'vitest';
2	
3	const VALID = {
4	  AUTH0_DOMAIN: 'dev-x.us.auth0.com',
5	  AUTH0_CLIENT_ID: 'id',
6	  AUTH0_CLIENT_SECRET: 'secret',
7	  AUTH0_SECRET: 'a'.repeat(64),
8	  APP_BASE_URL: 'https://mise.example',
9	  DATABASE_URL: 'REDACTED',
10	  GOOGLE_CLOUD_PROJECT: 'proj',
11	  DATAANDAPIS_KEY: 'k',
12	  OFF_USER_AGENT: 'Mise/0.1 (team@example.com)',
13	  RECIPE_FETCH_USER_AGENT: 'MiseRecipeFetcher/0.1',
14	  DEFAULT_TZ: 'America/Vancouver',
15	};
16	
17	async function loadEnv(vars: Record<string, string | undefined>, nodeEnv: 'test' | 'production' = 'test') {
18	  vi.resetModules();
19	  vi.unstubAllEnvs();
20	  for (const [k, v] of Object.entries(vars)) vi.stubEnv(k, v);
21	  vi.stubEnv('NODE_ENV', nodeEnv);
22	  vi.spyOn(console, 'error').mockImplementation(() => {});
23	  return (await import('./env')).getEnv;
24	}
25	
26	afterEach(() => {
27	  vi.unstubAllEnvs();
28	  vi.restoreAllMocks();
29	});
30	
31	describe('getEnv strict checks', () => {
32	  it('accepts a complete production env', async () => {
33	    const getEnv = await loadEnv(VALID, 'production');
34	    expect(getEnv().DEFAULT_TZ).toBe('America/Vancouver');
35	  });
36	
37	  it('requires APP_BASE_URL in production', async () => {
38	    const getEnv = await loadEnv({ ...VALID, APP_BASE_URL: undefined }, 'production');
39	    expect(() => getEnv()).toThrow(/Invalid environment/);
40	  });
41	
42	  it('rejects an AUTH0_SECRET shorter than 32 characters', async () => {
43	    const getEnv = await loadEnv({ ...VALID, AUTH0_SECRET: 'short' });
44	    expect(() => getEnv()).toThrow(/32 characters/);
45	  });
46	
47	  it('rejects a non-postgres DATABASE_URL and DATABASE_URL_TEST', async () => {
48	    const a = await loadEnv({ ...VALID, DATABASE_URL: 'mysql://x' });
49	    expect(() => a()).toThrow(/postgres:\/\//);
50	    const b = await loadEnv({ ...VALID, DATABASE_URL_TEST: 'http://x' });
51	    expect(() => b()).toThrow(/postgres:\/\//);
52	  });
53	
54	  it('rejects an invalid DEFAULT_TZ', async () => {
55	    const getEnv = await loadEnv({ ...VALID, DEFAULT_TZ: 'Mars/Olympus' });
56	    expect(() => getEnv()).toThrow(/IANA/);
57	  });
58	
59	  it('still tolerates missing variables in tests (partial parse)', async () => {
60	    const getEnv = await loadEnv({ GOOGLE_CLOUD_PROJECT: 'proj' });
61	    expect(getEnv().GOOGLE_CLOUD_PROJECT).toBe('proj');
62	  });
63	});
64	
65	describe('empty variables', () => {
66	  it('treats KEY= as unset: dev tolerates it, production reports it as missing', async () => {
67	    const dev = await loadEnv({ ...VALID, AUTH0_DOMAIN: '', ELEVENLABS_API_KEY: '' });
68	    expect(dev().AUTH0_DOMAIN).toBeUndefined();
69	    const prod = await loadEnv({ ...VALID, AUTH0_DOMAIN: '' }, 'production');
70	    expect(() => prod()).toThrow(/Invalid environment/);
71	  });
72	});
