1	import type * as D from './domain';
2	
3	export type ApiErrorCode =
4	  | 'UNAUTHORIZED' | 'BAD_REQUEST' | 'NOT_FOUND' | 'CONFLICT' | 'RATE_LIMITED'
5	  | 'UPSTREAM_UNAVAILABLE' | 'UNPROCESSABLE' | 'PAYLOAD_TOO_LARGE' | 'INTERNAL';
6	export interface ApiError { error: { code: ApiErrorCode; message: string; details?: unknown } }
7	
8	// ── Profile ────────────────────────────────────────────────────────────────
9	// GET  /api/me                → D.UserProfile
10	// PATCH /api/me               → D.UserProfile
11	// DELETE /api/me              → { ok: true }   deletes the users row (cascades to all of the user's data); client then logs out
12	export interface UpdateMeRequest {
13	  displayName?: string;
14	  tz?: string;
15	  dailyKcalGoal?: number | null;
16	  dailyProteinGoalG?: number | null;
17	  diets?: D.DietFlag[];
18	  allergens?: D.Allergen[];
19	  pastBestBeforeGraceDays?: number;           // integer 0–14
20	  completeOnboarding?: boolean;
21	}
22	
23	// ── Products ───────────────────────────────────────────────────────────────
24	// POST /api/products/lookup
25	export interface ProductLookupRequest { barcode: string }          // digits only, 8–14
26	export interface ProviderAttempt {
27	  provider: 'cache' | 'dataandapis' | 'openfoodfacts';
28	  result: 'hit' | 'miss' | 'error' | 'skipped';
29	  httpStatus?: number;
30	  ms: number;
31	}
32	export type ProductLookupResponse =
33	  | { status: 'found'; product: D.Product; cached: boolean; attempts: ProviderAttempt[] }
34	  | { status: 'not_found'; gtin: string; attempts: ProviderAttempt[] }
35	  | { status: 'invalid_barcode'; reason: 'length' | 'check_digit' | 'non_numeric' };
36	
37	// POST /api/vision/label   multipart/form-data: images (1–3 files, each ≤ 4 MB, jpeg/png/webp/heic), gtin?
38	export interface LabelExtractionResponse {
39	  isFoodProduct: boolean;
40	  draft: D.ProductDraft;                      // source = 'gemini_photo'
41	  flaggedFields: Array<keyof D.Nutrients | 'servingSize' | 'packageQuantity' | 'name'>;
42	  macrosConsistent: boolean | null;           // 4p + 4c + 9f ≈ kcal within ±20%
43	  confidence: 'high' | 'medium' | 'low';
44	  notes: string | null;
45	  model: string;
46	}
47	
48	// POST /api/vision/expiry  multipart/form-data: image (1 file ≤ 4 MB)
49	export interface ExpiryExtractionResponse {
50	  rawText: string | null;
51	  dateType: 'best_before' | 'expiry' | 'use_by' | 'packaged_on' | 'sell_by' | 'unknown';
52	  suggestedDate: D.ISODate | null;            // null if packaged_on or unreadable
53	  candidates: D.ISODate[];                    // >1 when order is ambiguous
54	  needsUserChoice: boolean;
55	  yearInferred: boolean;
56	  regexCrossCheck: 'agree' | 'disagree' | 'no_match';
57	  confidence: 'high' | 'medium' | 'low';
58	}
59	
60	// ── Pantry ─────────────────────────────────────────────────────────────────
61	// GET /api/pantry?sort=expiry|name&includeEmpty=false   → ListPantryResponse
62	export interface ListPantryResponse { items: D.PantryItem[] }
63	// POST /api/pantry                                      → D.PantryItem
64	export interface CreatePantryItemRequest {
65	  gtin?: string | null;
66	  name: string;
67	  brand?: string | null;
68	  quantity: number;                           // in displayUnit
69	  displayUnit: D.DisplayUnit;
70	  gramsPerUnit?: number | null;
71	  densityGPerMl?: number | null;
72	  expiryDate?: D.ISODate | null;
73	  expirySource?: 'photo' | 'manual' | null;
74	  expiryRawText?: string | null;
75	  nutritionBasis: '100g' | '100ml' | 'unit';
76	  nutrition?: D.Nutrients | null;             // per basis
77	  servingSizeBase?: number | null;
78	  allergenTags?: D.Allergen[];
79	  source: D.ProductSource;
80	  userVerified: boolean;
81	}
82	// PATCH /api/pantry/:id                                 → D.PantryItem
83	export type UpdatePantryItemRequest =
84	  Partial<Omit<CreatePantryItemRequest, 'source' | 'gtin'>> & { adjustReason?: 'manual_adjust' | 'discard' };
85	// DELETE /api/pantry/:id                                → { ok: true }
86	// POST /api/pantry/:id/restock   body: {}            → D.PantryItem   refill to the initial quantity, clear expiry, log pantry_events kind='add'
87	
88	// ── Recipes ────────────────────────────────────────────────────────────────
89	// POST /api/recipes/search   → application/x-ndjson stream of RecipeSearchEvent (one JSON per line)
90	export interface RecipeSearchRequest {
91	  mustUsePantryItemIds?: D.UUID[];            // default: items with daysToExpiry ≤ 3
92	  freeText?: string;                          // e.g. 'quick dinner', ≤ 100 chars
93	  maxResults?: number;                        // default 6, max 10
94	  extraDiets?: D.DietFlag[];                  // may only ADD to profile filters, never remove
95	}
96	export type RecipeSearchEvent =
97	  | { type: 'status'; stage: 'searching' | 'resolving' | 'fetching' | 'parsing' | 'checking_diet' | 'ranking'; message: string }
98	  | { type: 'search_suggestions'; html: string }      // Gemini searchEntryPoint.renderedContent, render unmodified
99	  | { type: 'candidate'; candidate: D.RecipeCandidate }
100	  | { type: 'excluded'; url: string; reason: 'no_recipe_markup' | 'fetch_failed' | 'diet_violation' | 'allergen' | 'duplicate' | 'blocked_url'; detail?: string }
101	  | { type: 'done'; total: number; excludedCount: number; cached: boolean }
102	  | { type: 'error'; error: ApiError['error'] };
103	
104	// GET /api/recipes/:id                                  → RecipeDetailResponse
105	export interface RecipeDetailResponse {
106	  original: D.OriginalRecipe;
107	  adaptations: D.AdaptedRecipe[];             // newest first; usually 0 or 1
108	  matches: D.PantryMatch[];
109	  score: D.RecipeScore;
110	  dietCheck: D.DietCheck;
111	  nutrition: { estimate: D.NutritionEstimate; publisher: D.Nutrients | null };
112	  adaptationNutrition: Record<D.UUID, D.NutritionEstimate>;   // keyed by adapted variantId
113	}
114	// POST /api/recipes/:id/adapt   body: {}                → AdaptResponse
115	//   409 CONFLICT  if no missing ingredients
116	//   422 UNPROCESSABLE if validation fails twice (allergen in substitute, unknown pantryItemId, …)
117	export interface AdaptResponse { adaptation: D.AdaptedRecipe; nutrition: D.NutritionEstimate }
118	
119	// ── Cooking ────────────────────────────────────────────────────────────────
120	// POST /api/cook/sessions                               → D.CookingSession
121	export interface StartSessionRequest { recipeId: D.UUID; variantId: D.UUID; servingsPlanned: number }
122	// GET /api/cook/sessions/:id                            → CookSessionView
123	export interface CookSessionView {
124	  session: D.CookingSession;
125	  recipe: { title: string; source: D.RecipeSource; servings: number; isAdapted: boolean };
126	  ingredients: Array<{ text: string; changed: boolean; scaledQtyDisplay: string | null; usedInSteps: number[] }>;
127	  steps: D.RecipeStep[];
128	  substitutions: D.Substitution[];            // empty for originals
129	}
130	// PATCH /api/cook/sessions/:id                          → D.CookingSession
131	export interface UpdateSessionRequest { currentStep?: number; status?: 'abandoned' }
132	// GET /api/cook/sessions/:id/finish-preview?servingsCooked=4   → FinishPreview
133	export interface DeductionLine {
134	  ingredientRaw: string;
135	  pantryItemId: D.UUID | null;
136	  pantryItemName: string | null;
137	  proposedQtyBase: number | null;             // scaled by servingsCooked / variant.servings
138	  availableQtyBase: number | null;
139	  dim: D.UnitDim | null;                      // the PANTRY item's dim (unit of availableQtyBase and of what /finish deducts), also on 'unconvertible' lines
140	  display: string;                            // 'Spinach: 150 g of 200 g → 50 g left'
141	  status: 'ok' | 'clamped' | 'unconvertible' | 'no_match' | 'staple';
142	}
143	export interface FinishPreview {
144	  deductions: DeductionLine[];
145	  nutritionPerServing: D.NutritionEstimate;
146	  publisherPerServing: D.Nutrients | null;
147	  suggestedLogPerServing: { kcal: number; proteinG: number; basis: 'estimate' | 'publisher' | 'low_coverage_estimate' };
148	  defaultServingsEaten: number;               // 1
149	}
150	// POST /api/cook/sessions/:id/finish                    → FinishResult
151	//   409 CONFLICT if session not in_progress (idempotency guard)
152	export interface FinishRequest {
153	  servingsCooked: number;                     // > 0, drives deduction
154	  servingsEaten: number;                      // ≥ 0, drives meal log (0 → no log)
155	  deductions: Array<{ pantryItemId: D.UUID; qtyBase: number }>;   // user-confirmed lines only
156	  perServingOverride?: { kcal: number; proteinG: number };
157	}
158	export interface FinishResult {
159	  session: D.CookingSession;
160	  pantryUpdates: Array<{ pantryItemId: D.UUID; name: string; beforeBase: number; afterBase: number }>;
161	  mealLog: D.MealLog | null;
