3	import { geminiJson } from '@/lib/gemini/client';
4	import { LABEL_SYSTEM_PROMPT, labelJsonSchema, labelSchema } from '@/lib/gemini/schemas';
5	import { handleRouteError, jsonOk } from '@/lib/http';
6	import { checkRateLimit } from '@/lib/rate-limit';
7	import { buildLabelResponse } from '@/server/vision/label';
8	import { readImages, visionUnavailable } from '@/server/vision/upload';
