10	export const runtime = 'nodejs';
11	
12	// SPEC F3. Returns a draft only; nothing is saved until the user confirms the form.
13	export async function POST(request: Request) {
14	  try {
15	    const user = await requireUser();
16	    const limit = checkRateLimit(user.id, 'vision');
17	    if (!limit.ok) throw new RateLimitedError('Too many photos. Try again in a moment.', limit.retryAfterMs);
18	
19	    const upload = await readImages(request, 'images', 3);
20	    if (!upload.ok) return upload.response;
21	    const gtin = upload.form.get('gtin');
22	
23	    try {
24	      const { data, model } = await geminiJson({
25	        system: LABEL_SYSTEM_PROMPT,
26	        text: 'Read this food product from its packaging and Nutrition Facts table.',
27	        images: upload.images,
28	        jsonSchema: labelJsonSchema,
29	        zod: labelSchema,
30	      });
31	      return jsonOk(buildLabelResponse(data, model, typeof gtin === 'string' ? gtin : null));
32	    } catch (err) {
33	      return visionUnavailable(err);
34	    }
35	  } catch (err) {
36	    return handleRouteError(err);
37	  }
38	}
