30	export function macrosConsistent(n: Pick<Nutrients, 'energyKcal' | 'proteinG' | 'carbohydrateG' | 'fatG'>): boolean | null {
31	  if (n.energyKcal == null || n.proteinG == null || n.carbohydrateG == null || n.fatG == null) return null;
32	  const estimate = 4 * n.proteinG + 4 * n.carbohydrateG + 9 * n.fatG;
33	  return Math.abs(estimate - n.energyKcal) <= Math.max(0.2 * n.energyKcal, MIN_KCAL_TOLERANCE);
34	}
35	
36	function draftGtin(given: string | null, printed: string | null | undefined): string | null {
37	  for (const code of [given, printed]) {
38	    if (!code) continue;
39	    const r = normalizeBarcode(code);
40	    if (r.ok) return r.gtin;
41	  }
42	  return null;
43	}
44	
45	export function buildLabelResponse(x: LabelExtraction, model: string, gtin: string | null): LabelExtractionResponse {
46	  const flags = new Set<Flag>();
47	
48	  const clean = (key: keyof Nutrients, v: number | null | undefined): number | null => {
49	    if (v == null) return null;
50	    if (v < 0) {
51	      flags.add(key);
52	      return null;
53	    }
54	    return v;
55	  };
56	
57	  const nutrients: Nutrients = {
58	    energyKcal: clean('energyKcal', x.calories_kcal),
59	    proteinG: clean('proteinG', x.protein_g),
60	    carbohydrateG: clean('carbohydrateG', x.carbohydrate_g),
61	    fatG: clean('fatG', x.fat_g),
62	    saturatedFatG: clean('saturatedFatG', x.saturated_fat_g),
63	    sugarsG: clean('sugarsG', x.sugars_g),
64	    fibreG: clean('fibreG', x.fibre_g),
65	    sodiumMg: clean('sodiumMg', x.sodium_mg),
66	  };
67	
68	  // The prompt asks for null calories and a note when the label only prints kJ.
69	  if (nutrients.energyKcal === null && x.calories_kcal == null) {
70	    const kj = KJ_IN_NOTES.exec(x.notes ?? '');
71	    if (kj) {
72	      nutrients.energyKcal = Math.round((Number(kj[1].replace(',', '.')) / 4.184) * 10) / 10;
73	      flags.add('energyKcal');
74	    }
75	  }
76	
77	  const consistent = macrosConsistent(nutrients);
78	  if (consistent === false) for (const k of ['energyKcal', 'proteinG', 'carbohydrateG', 'fatG'] as const) flags.add(k);
79	
80	  let servingSize: ProductDraft['servingSize'] = null;
81	  const v = x.serving_size_value;
82	  if (v != null && x.serving_size_unit && v >= 1 && v <= 1000) {
83	    servingSize = { value: v, unit: x.serving_size_unit, text: x.serving_size_text ?? null };
84	  } else if (v != null || x.serving_size_text || x.basis === 'per_serving') {
85	    flags.add('servingSize');
86	  }
87	
88	  // A label whose basis couldn't be read: its numbers can't be trusted to mean anything yet.
89	  if (x.basis === 'unknown') {
90	    flags.add('servingSize');
91	    for (const k of Object.keys(nutrients) as Array<keyof Nutrients>) if (nutrients[k] != null) flags.add(k);
92	  }
93	
94	  const packageValue = x.package_quantity_value;
95	  let packageQuantity: ProductDraft['packageQuantity'] = null;
96	  if (packageValue != null && x.package_quantity_unit && packageValue > 0) {
97	    packageQuantity = { value: packageValue, unit: PACKAGE_UNITS[x.package_quantity_unit] };
98	  } else if (packageValue != null) {
99	    flags.add('packageQuantity');
100	  }
101	
102	  const name = x.name?.trim() ?? '';
103	  if (x.is_food_product && name === '') flags.add('name');
104	
105	  const basis: ProductDraft['basis'] =
106	    x.basis === 'per_100g' ? '100g' : x.basis === 'per_100ml' ? '100ml' : x.basis === 'per_serving' || servingSize ? 'serving' : '100g';
107	
108	  return {
109	    isFoodProduct: x.is_food_product,
110	    draft: {
111	      gtin: draftGtin(gtin, x.barcode_digits_if_visible),
112	      name,
113	      brand: x.brand?.trim() || null,
114	      packageQuantity,
115	      servingSize,
116	      basis,
117	      nutrients,
118	      allergenTags: [],
119	      source: 'gemini_photo',
120	    },
121	    flaggedFields: x.is_food_product ? [...flags] : [],
122	    macrosConsistent: consistent,
123	    confidence: x.confidence,
124	    notes: x.notes ?? null,
125	    model,
126	  };
127	}
