2	// Applies db/migrations/*.sql in filename order against DATABASE_URL
3	// (or DATABASE_URL_TEST with --test). Tracks applied versions in
4	// schema_migrations. Each file runs in its own transaction.
5	import { readdir, readFile } from 'node:fs/promises';
6	import path from 'node:path';
7	import postgres from 'postgres';
8	
9	// Pick up .env.local like Next does (real env vars still win). Built into Node >= 21.7.
10	try {
11	  process.loadEnvFile(path.resolve(import.meta.dirname, '..', '.env.local'));
12	} catch {}
13	
14	const useTest = process.argv.includes('--test');
15	const url = useTest ? process.env.DATABASE_URL_TEST : process.env.DATABASE_URL;
16	if (!url) {
17	  console.error(`[migrate] missing ${useTest ? 'DATABASE_URL_TEST' : 'DATABASE_URL'}`);
18	  process.exit(1);
19	}
20	
21	const root = path.resolve(import.meta.dirname, '..');
22	const dir = path.join(root, 'db', 'migrations');
23	const files = (await readdir(dir)).filter((f) => f.endsWith('.sql')).sort();
24	
25	const sql = postgres(url, { max: 1, ssl: 'require', onnotice: () => {} });
26	
27	await sql`CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())`;
28	const applied = new Set((await sql`SELECT version FROM schema_migrations`).map((r) => r.version));
29	
30	for (const file of files) {
31	  if (applied.has(file)) {
32	    console.log(`[migrate] skip ${file} (already applied)`);
33	    continue;
34	  }
35	  const body = await readFile(path.join(dir, file), 'utf8');
36	  console.log(`[migrate] apply ${file} ...`);
37	  await sql.begin(async (tx) => {
38	    await tx.unsafe(body);
39	    await tx`INSERT INTO schema_migrations (version) VALUES (${file})`;
40	  });
41	  console.log(`[migrate] applied ${file}`);
42	}
43	
44	await sql.end();
45	console.log('[migrate] done');
