7	// Photos are held in memory for one request and never stored or logged (SPEC F3, F4, §13).
8	
9	export const MAX_IMAGE_BYTES = 4 * 1024 * 1024;
10	/** next's proxy buffers at most 10 MB of a body and silently truncates the rest. */
11	const MAX_BODY_BYTES = 10 * 1024 * 1024;
12	
13	const ALLOWED_TYPES = new Set<string>(['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif']);
14	
15	export type ReadImagesResult = { ok: true; images: GeminiImage[]; form: FormData } | { ok: false; response: NextResponse<ApiError> };
16	
17	const fail = (response: NextResponse<ApiError>): ReadImagesResult => ({ ok: false, response });
18	
19	export async function readImages(request: Request, field: string, max: number): Promise<ReadImagesResult> {
20	  if (Number(request.headers.get('content-length') ?? 0) > MAX_BODY_BYTES) {
21	    return fail(jsonError('PAYLOAD_TOO_LARGE', 'Those photos are too large. Try again with smaller ones.'));
22	  }
23	
24	  let form: FormData;
25	  try {
26	    form = await request.formData();
27	  } catch {
28	    return fail(jsonError('BAD_REQUEST', 'Expected a photo upload.'));
29	  }
30	
31	  const files = form.getAll(field).filter((f): f is File => f instanceof File);
32	  if (files.length === 0) return fail(jsonError('BAD_REQUEST', 'Add a photo first.'));
33	  if (files.length > max) return fail(jsonError('BAD_REQUEST', max === 1 ? 'Send one photo.' : `Send at most ${max} photos.`));
34	  if (files.some((f) => f.size > MAX_IMAGE_BYTES)) return fail(jsonError('PAYLOAD_TOO_LARGE', 'Each photo must be 4 MB or smaller.'));
35	  if (files.some((f) => !ALLOWED_TYPES.has(f.type))) return fail(jsonError('BAD_REQUEST', 'Photos must be JPEG, PNG, WebP or HEIC.'));
36	
37	  const images = await Promise.all(
38	    files.map(async (f) => ({ mimeType: f.type as GeminiImage['mimeType'], base64: Buffer.from(await f.arrayBuffer()).toString('base64') })),
39	  );
40	  return { ok: true, images, form };
41	}
42	
43	export function visionUnavailable(err: unknown): NextResponse<ApiError> {
44	  // Only the error's message: the request's photos must never reach the log.
45	  console.error('[vision] extraction failed:', err instanceof Error ? err.message : 'unknown error');
46	  return jsonError('UPSTREAM_UNAVAILABLE', "We couldn't read that photo. Try again, or enter the details by hand.");
47	}
