import type { ReceiptExtractionResponse } from '@/contracts/api';
import type { ReceiptExtraction } from '@/lib/gemini/schemas';

// Receipt-scan server checks. Gemini's output is untrusted: non-food lines are dropped here
// (this is the actual food-only enforcement point, not just UI), and every quantity/unit is
// sanity-checked before the user ever sees it. Pure.

const UNIT_MAP: Record<NonNullable<ReceiptExtraction['items'][number]['unit']>, ReceiptExtractionResponse['items'][number]['displayUnit']> = {
  g: 'g',
  kg: 'kg',
  ml: 'ml',
  l: 'l',
  oz: 'oz',
  lb: 'lb',
  fl_oz: 'fl_oz',
  count: 'pcs',
};

export function buildReceiptResponse(x: ReceiptExtraction, model: string): ReceiptExtractionResponse {
  const foodLines = x.items.filter((item) => item.is_food_item);
  const nonFoodCount = x.items.length - foodLines.length;

  const items = foodLines
    .map((item) => {
      const name = item.name.trim();
      const quantity = item.quantity != null && item.quantity > 0 ? item.quantity : null;
      const displayUnit = item.unit ? UNIT_MAP[item.unit] : 'pcs';
      return { name, quantity, displayUnit };
    })
    .filter((item) => item.name !== '');

  return {
    items,
    nonFoodCount,
    confidence: x.confidence,
    notes: x.notes ?? null,
    model,
  };
}

import { requireUser } from '@/lib/current-user';
import { RateLimitedError } from '@/lib/errors';
import { geminiJson } from '@/lib/gemini/client';
import { RECEIPT_SYSTEM_PROMPT, receiptJsonSchema, receiptSchema } from '@/lib/gemini/schemas';
import { handleRouteError, jsonOk } from '@/lib/http';
import { checkRateLimit } from '@/lib/rate-limit';
import { buildReceiptResponse } from '@/server/vision/receipt';
import { readImages, visionUnavailable } from '@/server/vision/upload';

export const runtime = 'nodejs';

// Receipt scan: returns a draft list of food items only; nothing is saved until the user
// confirms the review list.
export async function POST(request: Request) {
  try {
    const user = await requireUser();
    const limit = checkRateLimit(user.id, 'vision');
    if (!limit.ok) throw new RateLimitedError('Too many photos. Try again in a moment.', limit.retryAfterMs);

    const upload = await readImages(request, 'images', 3);
    if (!upload.ok) return upload.response;

    try {
      const { data, model } = await geminiJson({
        system: RECEIPT_SYSTEM_PROMPT,
        text: 'Read every purchased line item from this grocery receipt.',
        images: upload.images,
        jsonSchema: receiptJsonSchema,
        zod: receiptSchema,
      });
      return jsonOk(buildReceiptResponse(data, model));
    } catch (err) {
      return visionUnavailable(err);
    }
  } catch (err) {
    return handleRouteError(err);
  }
}

